import json, pathlib

base = pathlib.Path("/workspace/tmp-homelab-argocd/workloads/hermes")
fp = (base / "browser-fp" / "fp.js").read_text()
sup = (base / "browser-fp" / "supervisor.py").read_text()

header = """apiVersion: v1
kind: ConfigMap
metadata:
  name: hermes-browser-fp
  namespace: hermes
data:
  # GENERATED by browser-fp/gen_configmap.py from browser-fp/fp.js and
  # browser-fp/supervisor.py — edit those, re-run the generator, commit both.
  #
  # Identity shim + the injector that installs it. Mounted read-only at /browser-fp
  # in the chromium sidecar. fp.js runs at document_start in the page's main world:
  # it makes the session agree with itself (12 cores / 8 GB / Intel UHD 630 Mesa,
  # visible + focused page, audio devices present) instead of advertising a
  # software rasteriser and a backgrounded tab.
  #
  # Everything here is deliberately boring. The persona matches the environment it
  # actually sits in: Linux x86_64, America/New_York, Comcast residential egress,
  # 1600x1000 display, 1440x900 window. A Linux desktop with an Intel iGPU is
  # common; a Linux desktop with SwiftShader is not.
"""

def block(name, text):
    return "  %s: |\n%s\n" % (name, "\n".join("    " + ln for ln in text.rstrip("\n").split("\n")))

out = header + block("fp.js", fp) + block("supervisor.py", sup)
path = base / "browser-fp-configmap.yaml"
path.write_text(out)
print("wrote", path, len(out), "bytes")
